-- 13A pack 02 (OPTIONAL, independent of pack 01) APPLY: F-D get_ticket no longer returns the buyer e-mail
-- 13A ORDERS HARDENING: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/13a-orders-hardening/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL without Joe's relayed yes + a Sentinel pass + a backup. Apply AFTER 12A (12A's drift guard expects the original event_orders ACL/policies). See README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- The prod body of get_ticket was NOT captured. This pack renames the live function to get_ticket__orig_13a (body untouched, all grants revoked, original ACL stashed in its comment) and installs a wrapper that returns the original result minus the 'buyer' key.
-- Review PRECHECK-13A.sql output for get_ticket first (language, secdef, body, ACL, whether 'buyer' is a top-level key of the jsonb).
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded; a timeout set after a lock statement cannot bound that statement) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'), 'ABSENT');
  IF v IS DISTINCT FROM '1' THEN f := f || ('gt.overloads: expected 1 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket__orig_13a'), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('gt.helper_overloads: expected 0 but live is ' || v); END IF;
  v := coalesce((SELECT pg_get_function_identity_arguments(p.oid) FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'p_qr text' THEN f := f || ('gt.identity_args: expected p_qr text but live is ' || v); END IF;
  v := coalesce((SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'jsonb' THEN f := f || ('gt.ret: expected jsonb but live is ' || v); END IF;
  v := coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'postgres' THEN f := f || ('gt.owner: expected postgres but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('gt.exec_anon: expected true but live is ' || v); END IF;
  v := coalesce((SELECT (p.proacl IS NOT NULL)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('gt.acl_explicit: expected true but live is ' || v); END IF;
  v := coalesce((SELECT (SELECT count(*) FROM aclexplode(p.proacl) x WHERE x.is_grantable)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('gt.grant_options: expected 0 but live is ' || v); END IF;
  v := coalesce((SELECT (SELECT count(*) FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('gt.dependents: expected 0 but live is ' || v); END IF;
  v := coalesce((SELECT p.prosecdef::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('gt.secdef: expected true but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(obj_description(p.oid, 'pg_proc'), 'none') FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'none' THEN f := f || ('gt.comment: expected none but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '13A APPLY-02: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- stash the original ACL in the function's comment (the guard proved there is no comment today), rename the original, install the wrapper
DO $stash$
BEGIN
  EXECUTE format('COMMENT ON FUNCTION public.get_ticket(text) IS %L', 'ORIG_ACL=' || (SELECT p.proacl::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')));
END
$stash$;
ALTER FUNCTION public.get_ticket(text) RENAME TO get_ticket__orig_13a;
CREATE OR REPLACE FUNCTION public.get_ticket(p_qr text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r jsonb;
begin
  -- 13A F-D: the original body (renamed public.get_ticket__orig_13a by the apply pack, no grants to anyone but the owner) is called unchanged;
  -- this wrapper only removes the buyer's e-mail address ('buyer') from its result. Every other key is passed through byte-for-byte.
  r := public.get_ticket__orig_13a(p_qr);
  if r is not null and pg_catalog.jsonb_typeof(r) = 'object' then
    return r operator(pg_catalog.-) 'buyer'::text;
  end if;
  return r;
end;
$function$;
-- the wrapper gets exactly the original function's EXECUTE grants; the renamed original loses every grant but its owner's
DO $acl$
DECLARE
  h oid := to_regprocedure('public.get_ticket__orig_13a(text)'); a aclitem[]; own oid; r record;
BEGIN
  SELECT p.proacl, p.proowner INTO a, own FROM pg_proc p WHERE p.oid = h;
  REVOKE ALL ON FUNCTION public.get_ticket(text) FROM PUBLIC;
  FOR r IN SELECT DISTINCT x.grantee FROM aclexplode(a) x WHERE x.privilege_type = 'EXECUTE' AND x.grantee <> own LOOP
    IF r.grantee = 0 THEN GRANT EXECUTE ON FUNCTION public.get_ticket(text) TO PUBLIC;
    ELSE EXECUTE format('GRANT EXECUTE ON FUNCTION public.get_ticket(text) TO %I', pg_get_userbyid(r.grantee)); END IF;
  END LOOP;
  REVOKE ALL ON FUNCTION public.get_ticket__orig_13a(text) FROM PUBLIC;
  FOR r IN SELECT DISTINCT x.grantee FROM aclexplode(a) x WHERE x.grantee <> own AND x.grantee <> 0 LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION public.get_ticket__orig_13a(text) FROM %I', pg_get_userbyid(r.grantee));
  END LOOP;
END
$acl$;

DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'gt.overloads' AS name, coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_overloads' AS name, coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket__orig_13a'), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.identity_args' AS name, coalesce((SELECT pg_get_function_identity_arguments(p.oid) FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.ret' AS name, coalesce((SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.owner' AS name, coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.exec_anon' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.acl_explicit' AS name, coalesce((SELECT (p.proacl IS NOT NULL)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.grant_options' AS name, coalesce((SELECT (SELECT count(*) FROM aclexplode(p.proacl) x WHERE x.is_grantable)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.dependents' AS name, coalesce((SELECT (SELECT count(*) FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.secdef' AS name, coalesce((SELECT p.prosecdef::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.src_md5' AS name, coalesce((SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.config' AS name, coalesce((SELECT coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.lang' AS name, coalesce((SELECT (SELECT l.lanname FROM pg_language l WHERE l.oid = p.prolang)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_secdef' AS name, coalesce((SELECT p.prosecdef::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_owner' AS name, coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_nonowner_grants' AS name, coalesce((SELECT (SELECT count(*) FROM aclexplode(coalesce(p.proacl, acldefault('f',p.proowner))) x WHERE x.grantee <> p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_exec_anon_authenticated_public' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text||'/'||has_function_privilege('authenticated', p.oid, 'EXECUTE')::text||'/'||coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.helper_stash_present' AS name, coalesce((SELECT (coalesce(obj_description(p.oid, 'pg_proc'), '') ~ '^ORIG_ACL=')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'gt.wrapper_acl_equals_original' AS name, coalesce((SELECT ((SELECT coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket(text)')) = (SELECT '{'||string_agg(e, ',' ORDER BY e COLLATE "C")||'}' FROM unnest(string_to_array(trim(both '{}' from (SELECT substr(obj_description(p.oid, 'pg_proc'), 10) FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)'))), ',')) e))::text), 'ABSENT') AS actual
), e(name, expected) AS (VALUES
  ('gt.overloads', '1'),
  ('gt.helper_overloads', '1'),
  ('gt.identity_args', 'p_qr text'),
  ('gt.ret', 'jsonb'),
  ('gt.owner', 'postgres'),
  ('gt.exec_anon', 'true'),
  ('gt.acl_explicit', 'true'),
  ('gt.grant_options', '0'),
  ('gt.dependents', '0'),
  ('gt.secdef', 'true'),
  ('gt.src_md5', 'a13fcb2fcb58d332bdd16ac1a31b3e17'),
  ('gt.config', 'search_path=""'),
  ('gt.lang', 'plpgsql'),
  ('gt.helper_secdef', 'true'),
  ('gt.helper_owner', 'postgres'),
  ('gt.helper_nonowner_grants', '0'),
  ('gt.helper_exec_anon_authenticated_public', 'false/false/false'),
  ('gt.helper_stash_present', 'true'),
  ('gt.wrapper_acl_equals_original', 'true')
), r AS (SELECT e.name, e.expected, a.actual, (a.actual IS NOT DISTINCT FROM e.expected) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '13A APPLY-02: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;

