  UNION ALL SELECT 'gt.helper_owner' AS name, coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.get_ticket__orig_13a(text)')), 'ABSENT') AS actual
